window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"C-xyLYjnEP4","speaker":"Sheikh Sabah Al-Khaled Al-Hamad Al-Mubarak Al-Sabah","role":"Crown Prince","country":"Kuwait","region":"Middle East","url":"https://www.youtube.com/watch?v=C-xyLYjnEP4","date":"20260924","title":"🇰🇼 Kuwait - Crown Prince Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1161,"words":2447,"counts":{"claims":27,"promises":0,"attacks":7},"topics":[{"topic":"Iran","share":0.1879,"seconds":218},{"topic":"Yemen","share":0.1151,"seconds":134},{"topic":"Israel-Gaza","share":0.0777,"seconds":90},{"topic":"UNGA presidency","share":0.0685,"seconds":80},{"topic":"Kuwait-Iraq border","share":0.0654,"seconds":76},{"topic":"Syria","share":0.0651,"seconds":76},{"topic":"Middle East conflicts","share":0.0646,"seconds":75},{"topic":"UN Security Council reform","share":0.0619,"seconds":72},{"topic":"Kuwait development","share":0.0619,"seconds":72},{"topic":"Kuwait economy","share":0.0603,"seconds":70},{"topic":"International peace","share":0.0601,"seconds":70},{"topic":"Iraq-Kuwait relations","share":0.0577,"seconds":67},{"topic":"Ceremony","share":0.0537,"seconds":62}],"timeline":[[1,64,"Ceremony"],[66,146,"UNGA presidency"],[147,219,"UN Security Council reform"],[222,307,"Iran"],[308,374,"Iran"],[376,444,"Iran"],[445,512,"Iraq-Kuwait relations"],[514,590,"Kuwait-Iraq border"],[591,681,"Israel-Gaza"],[681,753,"Yemen"],[755,817,"Yemen"],[818,894,"Syria"],[894,970,"Middle East conflicts"],[970,1042,"Kuwait development"],[1043,1113,"Kuwait economy"],[1115,1185,"International peace"]],"stances":{"Ceremony":"Sheikh Sabah conveys greetings from the Amir of Kuwait to the assembly.","UNGA presidency":"Sheikh Sabah expresses congratulations to the newly elected president and gratitude to the outgoing president, while affirming support for their themes and efforts.","UN Security Council reform":"Sheikh Sabah emphasizes the urgent need for UN Security Council reform to make it more representative, effective, and transparent.","Iran":"Sheikh Sabah condemns Iran's obstruction of maritime navigation and closing of the Strait of Hormuz as a violation of international law aimed at disrupting global trade.","Iraq-Kuwait relations":"Sheikh Sabah Al-Khaled Al-Hamad Al-Mubarak Al-Sabah expresses strong support for Iraq's stability and security, commends recent measures by the Iraqi Prime Minister, and calls for enhanced bilateral cooperation.","Kuwait-Iraq border":"Sheikh Sabah calls for adherence to international law and bilateral agreements while urging Iraq to cooperate on prisoner issues.","Israel-Gaza":"Sheikh Sabah Al-Khaled Al-Hamad Al-Mubarak Al-Sabah condemns Israeli occupation forces, calls for their withdrawal from Gaza, and supports sanctions against settlers.","Yemen":"Sheikh Sabah Al-Khaled Al-Hamad Al-Mubarak Al-Sabah states that Kuwait fully supports UN-led efforts for a Yemen-led settlement and affirms that any political solution must safeguard Yemen's unity, sovereignty, independence, and territorial integrity.","Syria":"Sheikh Sabah affirms support for a Syrian-led political process, stresses the need to respect Syria's sovereignty and unity, and condemns Israeli incursions into Syrian territory.","Middle East conflicts":"Sheikh Sabah calls for Israel's withdrawal from occupied Lebanese territories and advocates for peaceful political dialogue in Sudan, Somalia, and Libya to protect their sovereignty.","Kuwait development":"Sheikh Sabah states that Kuwait bases its diplomacy on the Kuwait Fund for Arab Economic Development and is progressing towards Vision 2035 through economic diversification and digital transformation.","Kuwait economy":"Sheikh Sabah states that institutional efficiency and economic competitiveness will establish Kuwait as a leading regional financial center.","International peace":"Sheikh Sabah asserts that a just peace, respect for sovereignty, and adherence to international law are essential for global stability."},"claims":[{"t":72,"quote":"congratulate his excellency Dr. Khalil Rahman and the friendly people People People's Republic of Bangladesh on his election as president of the General Assembly.","topic":"UNGA presidency","kind":"fact"},{"t":120,"quote":"initiatives such as and the pact for the future as well as the ongoing efforts to address global challenges, crisis, conflicts, wars, climate change and terrorism","topic":"UNGA presidency","kind":"fact"},{"t":175,"quote":"security council is the body charged with maintaining international peace and security has become essential to keep pace with the significant increase in the number of member states and the changes in international relations since the establishment of the There is an urgent need for the council to become more representative, effective, and transparent in carrying out its responsibilities.","topic":"UN Security Council reform","kind":"fact"},{"t":202,"quote":"since last February, the state of Kuwait, the countries of the Gulf Cooperation Council and the Hashite Kingdom of Jordan have been subjected to illegal Iranian aggression involving ballistic ballistic missiles, cruise missiles, and drones.","topic":"UN Security Council reform","kind":"fact"},{"t":234,"quote":"These brutal attacks have systematically and repeatedly targeted civilian objects and critical infrastructure, including Kuwait International Airport, power and water stations, oil facilities as well","topic":"Iran","kind":"fact"},{"t":265,"quote":"They have also resulted in numerous injuries and have inflicted material and economic damage","topic":"Iran","kind":"fact"},{"t":283,"quote":"Iran is obstructing maritime navigation and closing the strait of Hormuz to use it as a bargaining chip in the war","topic":"Iran","kind":"fact"},{"t":308,"quote":"We also salute the countries that have sponsored Security Council resolution 2817 and other resolutions issued by the Human Rights Council and the International Maritime Organization, which have condemned the Iranian aggression as a threat to international peace and security.","topic":"Iran","kind":"fact"},{"t":330,"quote":"affirming the inherent rights of states to self-defense as per article 51 of the UN charter.","topic":"Iran","kind":"fact"},{"t":407,"quote":"addressing the security concerns of all countries in the region, including the Iranian nuclear file, ballistic missiles and drones","topic":"Iran","kind":"fact"},{"t":421,"quote":"right of passage through the straits of Hormuz and Babel Mandab in accordance with the international law and the 1982 UN convention on law of the sea","topic":"Iran","kind":"fact"},{"t":458,"quote":"since the fall of the former regime in 2003","topic":"Iraq-Kuwait relations","kind":"fact"},{"t":461,"quote":"Kuwait has supported and stood by Iraq fa in facing security, political and economic challenges","topic":"Iraq-Kuwait relations","kind":"fact"},{"t":517,"quote":"the maritime border demarcation beyond marker 162 as per the rules of international law and the 1982 UN convention on law of the sea","topic":"Kuwait-Iraq border","kind":"fact"},{"t":541,"quote":"Very important among these agreements is the Abdullah uh agreement and the 2008 security exchange protocol","topic":"Kuwait-Iraq border","kind":"fact"},{"t":604,"quote":"The Palestinian people continue to suffer under difficult living conditions caused by policies of displacement, arrests, and settlement.","topic":"Israel-Gaza","kind":"fact"},{"t":614,"quote":"We call for the full implementation of the comprehensive peace plan and its sub subsequent phase adopted by security council resolution 2803.","topic":"Israel-Gaza","kind":"fact"},{"t":704,"quote":"the sisterly Republic of Yemen is witnessing a serious military escalation as a result of the attacks by Houthi militias against several governorates and areas along the west coast aimed at threatening navigation in the Babel Mandab Strait.","topic":"Yemen","kind":"fact"},{"t":773,"quote":"We also condemn in the strongest terms the attacks by the Houthis against the sisterly kingdom of Saudi Arabia targeting civilian and economic facilities in several cities.","topic":"Yemen","kind":"fact"},{"t":786,"quote":"In this context, we affirm that the security of the Kingdom of Saudi Arabia is an integral part of the security of the state of Kuwait and the security of the GCC states.","topic":"Yemen","kind":"fact"},{"t":851,"quote":"We condemn and reject the attacks and incursions by Israeli occupation forces into Syrian territory. These acts are a serious escalation and a violation of the 1974 disengagement of forces agreement.","topic":"Syria","kind":"fact"},{"t":897,"quote":"maintaining an international presence along the blue line to ensure the full implementation of UN resolution 1701","topic":"Middle East conflicts","kind":"fact"},{"t":943,"quote":"Kuwait's independence, our foreign policy was based on firm principles, namely moderation and balance and a firm commitment to the charter of the United Nations and international law and on support for multilateralism","topic":"Middle East conflicts","kind":"self_credit"},{"t":997,"quote":"Since 1961, the fund has contributed to financing development projects in 107 countries.","topic":"Kuwait development","kind":"number"},{"t":1043,"quote":"These efforts should enhance the efficiency of institutions and the competitiveness of the economy and will establish Kuwait as a leading financial commercial and control center in the region.","topic":"Kuwait economy","kind":"fact"},{"t":1059,"quote":"my country has known the cruelty of occupation and the bitterness of aggression and has suffered from wars that have ravaged and continue to ravage our region for four decades.","topic":"Kuwait economy","kind":"fact"},{"t":1123,"quote":"a just peace is the path to stability and that respect for state sovereignty, the preservation of the rights of people and recourse to international law for resolving disputes are indispensable pillars for security and stability of all states","topic":"International peace","kind":"fact"}],"promises":[],"attacks":[{"t":212,"quote":"illegal Iranian aggression involving ballistic ballistic missiles, cruise missiles, and drones.","topic":"UN Security Council reform","target":"Iran"},{"t":259,"quote":"These heinous attacks have claimed the lives of several martyrs and innocent civilians","topic":"Iran","target":"Iran"},{"t":283,"quote":"Iran is obstructing maritime navigation and closing the strait of Hormuz to use it as a bargaining chip in the war in violation of international law","topic":"Iran","target":"Iran"},{"t":320,"quote":"condemned the Iranian aggression as a threat to international peace and security. demanding its cessation","topic":"Iran","target":"Iran"},{"t":597,"quote":"condemning the ongoing violations by the Israeli occupation forces against the brotherly Palestinian people.","topic":"Israel-Gaza","target":"Israel"},{"t":773,"quote":"We also condemn in the strongest terms the attacks by the Houthis against the sisterly kingdom of Saudi Arabia targeting civilian and economic facilities in several cities.","topic":"Yemen","target":"Houthis"},{"t":851,"quote":"We condemn and reject the attacks and incursions by Israeli occupation forces into Syrian territory.","topic":"Syria","target":"Israel"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Ceremony","text":"The assembly will now hear an address by His Highness Shik Sabah Al Khaled Alhammed al-Mubarak al- Sabah, Crown Prince of the State of Q8. I request protocol to accompany his highness. I invite him to address the assembly. Thank you, Mr. President. In the name of God, most compassionate, most merciful, your excellency, President of the General Assembly, your Excellency, Secretary General, Your Majesties, Excellencies, Highnesses, ladies and gentlemen, may the peace and blessings of God be upon you. At the outset, I am pleased to convey to you the greetings of his highness, the amir of the state of Kuwait, Sheikh Mal al Ahmed al Jabir al- Sabah."},{"t":66,"topic":"UNGA presidency","text":"Along with his wishes for the success of this session, we would also like to congratulate his excellency Dr. Khalil Rahman and the friendly people People People's Republic of Bangladesh on his election as president of the General Assembly. We affirm our support for his excellency and we salute his wise choice of theme for this session. Restoring trust and managing transformation, a united nations that delivers for all. We would also like to express our gratitude to her excellency Miss Analina Berboka for her valued efforts during her presidency of the previous session. We would be remiss not to applaud the efforts, good offices and initiatives of the secretary general aimed at strengthening multilateralism and that include initiatives such as and the pact for the future as well as the ongoing efforts to address global challenges, crisis, conflicts, wars, climate change and terrorism as well as the efforts to assist member states in order to achieve these sustainable development goals and to strengthen international cooperation on artificial ele intelligence."},{"t":147,"topic":"UN Security Council reform","text":"We hope that these efforts will continue beyond the conclusion of the secretary general's term in an in a manner to guarantee the continuity of work to reform and develop the organization's body's enhance its effectiveness and performance in discharging its responsibilities. In this context, we emphasize that security council reform and the security council is the body charged with maintaining international peace and security has become essential to keep pace with the significant increase in the number of member states and the changes in international relations since the establishment of the There is an urgent need for the council to become more representative, effective, and transparent in carrying out its responsibilities. Mr. President, uh, since last February, the state of Kuwait, the countries of the Gulf Cooperation Council and the Hashite Kingdom of Jordan have been subjected to illegal Iranian aggression involving ballistic ballistic missiles, cruise missiles, and drones."},{"t":222,"topic":"Iran","text":"All while we are not a party to the conflict in the region. These attacks are a flagrant violation of the international law, international humanitarian law and the UN charter. These brutal attacks have systematically and repeatedly targeted civilian objects and critical infrastructure, including Kuwait International Airport, power and water stations, oil facilities as well, revealing a hostile approach aimed at disrupting the foundations of life and critical infrastructure. These heinous attacks have claimed the lives of several martyrs and innocent civilians. They have also resulted in numerous injuries and have inflicted material and economic damage. And furthermore, to inflict harm on the economies of the region and the world and to disrupt global trade and oil markets, Iran is obstructing maritime navigation and closing the strait of Hormuz to use it as a bargaining chip in the war in violation of international law and the relevant security council In this regard, the state of Kuwait expresses its deep appreciation to the brotherly and friendly nations who have stood by Kuwait and demonstrated solidarity."},{"t":308,"topic":"Iran","text":"We also salute the countries that have sponsored Security Council resolution 2817 and other resolutions issued by the Human Rights Council and the International Maritime Organization, which have condemned the Iranian aggression as a threat to international peace and security. demanding its cessation and affirming the inherent rights of states to self-defense as per article 51 of the UN charter. They have also stressed the importance of guaranteeing freedom of navigation without restrictions or conditions and based on Kuwait's belief that the security and stability of the Arabian Gulf region constitutes a fundamental pillar of regional and international security and stability as demonstrated by the repercussions of the war and Iranian We reiterate the support for all diplomatic efforts aimed at deescalation and a peaceful resolution to the existing dispute."},{"t":376,"topic":"Iran","text":"And we applaud the mediation efforts led by Qatar and Pakistan while emphasizing the need to reach a sustainable regional understanding based on a firm commitment to the principles of good neighborliness, respect for state sovereignty and a non-interference in internal affairs as well as refraining from the use or threat uh of use of In addition to seizing support for proxies and militias and addressing the security concerns of all countries in the region, including the Iranian nuclear file, ballistic missiles and drones while stressing the guarantee of freedom and safety of navigation and the right of passage through the straits of Hormuz and Babel Mandab in accordance with the international law and the 1982 UN convention on law of the sea. Mr. President, the state of Kuwait is committed in its foreign policy to the principles of the UN charter, in particular, respect for the principle of good neighborliness, respect for state sovereignty, and the non-inference in internal affairs."},{"t":445,"topic":"Iraq-Kuwait relations","text":"Accordingly, the state of Kuwait views the brotherly Republic of Iraq as a neighbor with whom we share close ties as a and are partners in security and stability since the fall of the former regime in 2003. Kuwait has supported and stood by Iraq fa in facing security, political and economic challenges in order to help Iraq restore its regional and international role in standing. Kuwait believes that a stable, secure, and prosperous Iraq serves the shared interests of Kuwait and the entire region. In this context, the state of Kuwait commends the measures taken by the Iraqi Prime Minister, Mr. Ali Alzi, to consolidate arms under state control and to strengthen Iraq's bilateral relations with neighboring countries. We look forward to enhancing confidence building measures between the two countries and to elevate our bilateral relations to broader horizons as well as to resolve all outstanding issues."},{"t":514,"topic":"Kuwait-Iraq border","text":"Most important of these issues are the maritime border demarcation beyond marker 162 as per the rules of international law and the 1982 UN convention on law of the sea. We also emphasize the need to adhere to bilateral security and technical agreements and arrangements signed between the two countries. Very important among these agreements is the Abdullah uh agreement and the 2008 security exchange protocol. These agreements serve as vital legal and practical instruments for regulating navigation, protecting the environment, combating terrorism, as well as combating the illicit trafficking of arms and narcotics, and enhancing shared security. The state of quit calls upon Iraq to cooperate with the high level representative of the secretary general pursuant to security council resolution 2792 in order to achieve the progress and desired outcomes regarding Kuwaiti prisoners and missing persons as well as nationals of third countries and the recovery of Kuwaiti property including the national archives."},{"t":591,"topic":"Israel-Gaza","text":"Mr. Mr. President, the state of Kuwait reiterates its principled and firm position condemning the ongoing violations by the Israeli occupation forces against the brotherly Palestinian people. The Palestinian people continue to suffer under difficult living conditions caused by policies of displacement, arrests, and settlement. We call for the full implementation of the comprehensive peace plan and its sub subsequent phase adopted by security council resolution 2803. This includes the complete withdrawal of Israeli occupation forces from Gaza, the assurance of humanitarian aid access and the return of the Palestinian Authority to the Gaza Strip. We affirm that the Gaza Strip is an integral part of the occupied Palestinian territory. In this regard, we welcome the measures and decisions taken by the United Kingdom, France, and several other nations to condemn settlement activities and to impose sanctions against settlers involved in acts of violence and terrorism against Palestinians as well as banning the import of goods and products originating from the The state of Kuwait reiterates that a just, comprehensive, and lasting peace in the region remains contingent upon an"},{"t":681,"topic":"Yemen","text":"end to the Israeli occupation of all Arab territories, as well as enabling the Palestinian people to exercise their legitimate and inalienable rights. It also rests upon the establishment of an independent Palestinian state on the borders of June 4th, 1967 with East Jerusalem as its capital. Mr. President, the sisterly Republic of Yemen is witnessing a serious military escalation as a result of the attacks by Houthi militias against several governorates and areas along the west coast aimed at threatening navigation in the Babel Mandab Strait. In this regard, the state of Kuwait reiterated its full support for UN-led efforts aimed at a comprehensive, sustainable and Yemenled settlement in accordance with the three agreed references and the relevant security council resolutions, in particular resolution The state of Kuwait affirms that any political settlement must safeguard Yemen's unity, sovereignty, independence, and territorial integrity."},{"t":755,"topic":"Yemen","text":"A settlement must end the suffering of the Yemeni people and must open prospects for security, stability, and economic development. We also stress the need to preserve the security and safety of maritime navigation in the Red Sea and the Babel Mandabub Strait. We also condemn in the strongest terms the attacks by the Houthis against the sisterly kingdom of Saudi Arabia targeting civilian and economic facilities in several cities. In this context, we affirm that the security of the Kingdom of Saudi Arabia is an integral part of the security of the state of Kuwait and the security of the GCC states. Mr. Mr. President, the state of Kuwait reiterates its solidarity with the sisterly Syrian Arab Republic. We welcome the measures taken by the international community to lift the sanctions against Syria and to remove Syria's name from the list of state sponsors of terrorism."},{"t":818,"topic":"Syria","text":"We also affirm our support for all efforts aimed at rebuilding state institutions and aimed at advancing a Syrian-led comprehensive inclusive political process led by the Syrians with the active participation of all segments of society in Syria and aimed at fulfilling their aspirations for security, stability, and a life of dignity. In this context, we stress the need to respect Syria's sovereignty, unity, and territorial We condemn and reject the attacks and incursions by Israeli occupation forces into Syrian territory. These acts are a serious escalation and a violation of the 1974 disengagement of forces agreement. They undermine security and stability in the region. With regards to the sisterly Lebanese Republic, the state of Kuwait affirms the importance of Lebanese state institutions and the need to extend their full authority over the entire territory of Lebanon and to restrict the possession of arms exclusively to the state, thereby reinforcing Lebanon's sovereignty and preserving its security and stability."},{"t":894,"topic":"Middle East conflicts","text":"Here we also emphasize the importance of maintaining an international presence along the blue line to ensure the full implementation of UN resolution 1701. And we reiterate our demand for Israel's withdrawal from all occupied Lebanese territories. And with regards to developments in the Republic of Sudan, the Federal Republic of Somalia, and the state of Libya, we affirm the need to adhere to peaceful resolution and to engage in political dialogue to resolve disputes as per the relevant security council resolutions and the principles of international law so as to protect the unity, territorial integrity, and sovereignty of these sisterly nations. Mr. Mr. President, since Kuwait's independence, our foreign policy was based on firm principles, namely moderation and balance and a firm commitment to the charter of the United Nations and international law and on support for multilateralism and the belief that dialogue and the peaceful settlement of disputes are the best means to maintain international peace and security."},{"t":970,"topic":"Kuwait development","text":"The state of Kuwait also believes in a complimentary relationship between security and development. There can be no security without development and no development without security. Accordingly, Kuwait has uh based its uh development and humanitarian diplomacy uh on a pioneering role for the Kuwait Fund for Arab Economic Development. Since 1961, the fund has contributed to financing development projects in 107 countries. This stems from a belief that addressing the root causes of crisis is not limited to security measures, but requires supporting development, providing the foundations for a life of dignity, and building more resilient and stable societies. At the national level, Kuwait is confidently progressing towards its Kuwait vision 2035 by accelerating the implementation of development projects, diversifying its economy and sources of income, continuing its digital transformation, empowering women and youth, developing its legislation, and consolidating governance and transparency."},{"t":1043,"topic":"Kuwait economy","text":"These efforts should enhance the efficiency of institutions and the competitiveness of the economy and will establish Kuwait as a leading financial commercial and control center in the region. In conclusion, Mr. President, my country has known the cruelty of occupation and the bitterness of aggression and has suffered from wars that have ravaged and continue to ravage our region for four decades. From this experience, we have realized that they are the people who pay the price of conflicts. We have recognized the need for the world to stand together united in support of justice and in adherence to the UN charter and international law. Out of our experience, we became firmly convinced that peace is the choice of wisdom and is protected by ability and dialogue does not diminish rights, but preserves them. And that security is not protected by force alone, but it is anchored in justice, the rule of law, and the principles of international legitimacy."},{"t":1115,"topic":"International peace","text":"The message of the state of Kuwait is one that has embraced in both word and deed and to which it remains committed that a just peace is the path to stability and that respect for state sovereignty, the preservation of the rights of people and recourse to international law for resolving disputes are indispensable pillars for security and stability of all states. The state of Kuwait shall remain, as the world has known it to be, a voice of wisdom and moderation, a proponent of dialogue, cooperation, and openness to partnerships that serve mutual interests, a champion of justice, and a partner in consolidating international peace and security. We believe that peace is the path to a future where rights are protected, nations are stable, and generations enjoy security and prosperity. And may the peace and blessings of God be upon you. On behalf of the assembly, I wish to thank the crown prince of the state of"}],"compare":[{"topic":"Iran","share":0.2141,"mean":0.0127,"rank":3,"others":25},{"topic":"Middle East","share":0.1393,"mean":0.0066,"rank":1,"others":19},{"topic":"Yemen","share":0.1311,"mean":0.0031,"rank":2,"others":4},{"topic":"Israel–Palestine","share":0.0885,"mean":0.0522,"rank":44,"others":76},{"topic":"Kuwait","share":0.0745,"mean":0.0,"rank":1,"others":0},{"topic":"Syria","share":0.0742,"mean":0.0031,"rank":3,"others":7},{"topic":"UN & its reform","share":0.0706,"mean":0.2055,"rank":160,"others":170},{"topic":"International Law & Order","share":0.0685,"mean":0.0604,"rank":65,"others":102}]};
